window.__WB_TEXTBOOK__ = [{"id": "net_topdown", "name": "计算机网络：自顶向下方法 + Computer Networks", "author": "James F. Kurose, Keith W. Ross & Andrew S. Tanenbaum", "level": "核心必修 · 协议栈与通信原理", "chapters": [{"cid": "net_ch1", "title": "第1章 网络体系结构与性能指标：分层模型、四类时延与吞吐量", "summary": "本章从宏观视角构建分组交换网络的体系结构与定量评估模型。现代互联网采用五层协议栈（应用、传输、网络、链路、物理），通过封装与解封装实现端到端解耦。端到端节点总时延由四部分叠加：$d_{nodal} = d_{proc} + d_{queue} + d_{trans} + d_{prop}$，其中传输时延 $d_{trans} = L/R$（分组长度除以链路速率），传播时延 $d_{prop} = d/s$（物理距离除以信号速度）。与电路交换独占固定带宽不同，分组交换凭借统计多路复用提高链路利用率，但在突发流量下会产生排队时延甚至丢包。网络吞吐量受限于路径上的最小速率段即瓶颈链路（Bottleneck Link），而时延带宽积 $BDP = R \\times d_{prop}$ 决定了管道中在途比特的最大容量。", "template_cpp": "// 端到端分组交换时延与流水线并行传输耗时模型\n#include <algorithm>\ndouble e2e_packet_delay(int N_links, double L_bits, double R_bps, double dist_m, double speed_mps) {\n    double d_trans = L_bits / R_bps;\n    double d_prop  = dist_m / speed_mps;\n    return N_links * (d_trans + d_prop);\n}\n// P 个分组连续流水线发送过 N 条同速链路:\ndouble pipelined_delay(int P, int N, double d_trans, double d_prop) {\n    return (P + N - 1) * d_trans + N * d_prop;\n}", "pitfalls": "1. 混淆传输时延 $L/R$ 与传播时延 $d/s$：提升链路带宽 $R$ 只能减小 $d_{trans}$，无法缩短物理传播时间 $d_{prop}$；2. 单位换算陷阱：网络速率常用 $1\\text{ Mbps} = 10^6\\text{ bps}$（十进制），而文件大小常用 $1\\text{ MiB} = 2^{20}\\text{ Bytes} = 8 \\times 2^{20}\\text{ bits}$；3. 忽略分组交换中多跳路由器的流水线效应，把 $P$ 个分组总耗时误算为 $P \\times N \\times d_{trans}$。", "workbench_tags": ["五层协议栈", "四类节点时延", "分组交换流水线", "瓶颈链路吞吐量"], "problems": [{"oj": "教材精选题", "pid": "NET-1.1", "title": "大文件分片过三跳路由器的流水线传输耗时", "diff": "基础", "hint": "破题思路：发送 $8\\text{ Mbit}$ 文件经 3 条 $2\\text{ Mbps}$ 链路（忽略传播与处理时延），比较整包发送与拆分为 $1000$ 个 $8\\text{ Kbit}$ 分组的时间。\n解答要点：整包发送时每跳耗时 $8 / 2 = 4\\text{ s}$，3 跳串行共 $3 \\times 4 = 12\\text{ s}$。拆分为 $P = 1000$ 个分组后，单分组每跳耗时 $8\\text{ Kbit} / 2\\text{ Mbps} = 4\\text{ ms}$，流水线总耗时为 $(1000 + 3 - 1) \\times 4\\text{ ms} = 4.008\\text{ s}$，加速近 3 倍。"}, {"oj": "教材精选题", "pid": "NET-1.2", "title": "统计多路复用 vs 电路交换并发用户容量对比", "diff": "中档", "hint": "破题思路：$1\\text{ Mbps}$ 共享链路，每个用户活跃时占 $100\\text{ kbps}$ 且活跃概率 $p = 0.1$。\n解答要点：电路交换固定分配槽位，最多支持 $1\\text{ Mbps} / 100\\text{ kbps} = 10$ 个用户。分组交换下若接入 $N = 35$ 个用户，仅当同时活跃人数 $k \\ge 11$ 时才拥塞，其概率为 $\\sum_{k=11}^{35} \\binom{35}{k} (0.1)^k (0.9)^{35-k} \\approx 0.0004$（二项分布尾部极小），分组交换以极低拥塞率支撑了 $3.5$ 倍并发用户。"}, {"oj": "教材精选题", "pid": "NET-1.3", "title": "多流共享瓶颈链路时的端到端吞吐量计算", "diff": "中档", "hint": "破题思路：10 个客户端同时从服务器下载，接入链路各为 $R_c = 2\\text{ Mbps}$，服务器出口 $R_s = 10\\text{ Mbps}$，核心骨干共有瓶颈链路 $R = 15\\text{ Mbps}$。\n解答要点：共享核心链路每条流平分 $15 / 10 = 1.5\\text{ Mbps}$；服务器出口每条流分得 $10 / 10 = 1.0\\text{ Mbps}$；客户端接入上限为 $2\\text{ Mbps}$。受限于木桶效应 $\\min(2, 1.0, 1.5) = 1.0\\text{ Mbps}$，每条连接吞吐量为 $1.0\\text{ Mbps}$。"}, {"oj": "教材精选题", "pid": "NET-1.4", "title": "分组头开销与最佳分组大小权衡推导", "diff": "压轴", "hint": "破题思路：报文总长 $M$ 比特，拆分为载荷长 $L$、报头长 $h$ 的分组（共 $M/L$ 个分组），过 $N$ 条速率为 $R$ 的链路，求最小化总传输时间的最佳载荷 $L^*$。\n解答要点：总时间 $T(L) = \\left(\\frac{M}{L} + N - 1\\right) \\frac{L + h}{R}$。展开并忽略常数项后，关于 $L$ 求导 $\\frac{dT}{dL} = \\frac{1}{R}\\left((N - 1) - \\frac{Mh}{L^2}\\right) = 0$，解得最优分组载荷 $L^* = \\sqrt{\\frac{Mh}{N - 1}}$。"}]}, {"cid": "net_ch2", "title": "第2章 物理层与数据通信：奈奎斯特准则、香农定理与编码调制", "summary": "本章聚焦信道物理极限与数字基带/频带传输理论。在无噪声理想低通信道中，带宽为 $B\\text{ Hz}$ 的信道最高码元速率受奈奎斯特定理限制为 $2B$ 波特，若每个码元携带 $V$ 种离散电平，则极限数据速率为 $C = 2B \\log_2 V\\text{ bps}$。在存在加性高斯白噪声（AWGN）的实际信道中，香农（Shannon）信道容量定理给出了绝对上限：$C = B \\log_2(1 + S/N)\\text{ bps}$，其中信噪比常以分贝 $\\text{SNR}_{dB} = 10 \\log_{10}(S/N)$ 给出。物理层基带编码中，曼彻斯特编码在每个比特中间发生电平跳变，兼具自同步时钟与抗直流漂移能力，但编码效率仅为 $50\\%$；而 4B/5B 与 8B/10B 编码通过映射冗余比特兼顾了高效率与时钟同步。", "template_cpp": "// 物理层奈奎斯特与香农信道极限容量计算\n#include <cmath>\ndouble nyquist_capacity(double B_hz, int levels_V) {\n    return 2.0 * B_hz * std::log2(levels_V);\n}\ndouble shannon_capacity(double B_hz, double snr_db) {\n    double snr_linear = std::pow(10.0, snr_db / 10.0);\n    return B_hz * std::log2(1.0 + snr_linear);\n}", "pitfalls": "1. 忘记把分贝单位的信噪比 $\\text{SNR}_{dB}$ 还原为线性比值 $S/N = 10^{\\text{dB}/10}$ 就直接代入香农公式；2. 混淆“波特率（Baud，码元/秒）”与“比特率（bps，比特/秒）”，当采用 16-QAM（$V=16$）调制时，1 个码元携带 4 比特；3. 在曼彻斯特编码中误认为电平高低代表 0/1，实际上是中间跳变方向（如 IEEE 802.3 中低到高为 1、高到低为 0）决定比特值。", "workbench_tags": ["奈奎斯特定理", "香农公式", "曼彻斯特编码", "波特率与比特率"], "problems": [{"oj": "教材精选题", "pid": "NET-2.1", "title": "电话信道带宽与信噪比下的香农极限容量", "diff": "基础", "hint": "破题思路：标准语音电话信道带宽 $B = 3000\\text{ Hz}$，信噪比 $\\text{SNR} = 30\\text{ dB}$。\n解答要点：先换算线性信噪比 $S/N = 10^{30/10} = 1000$。代入香农公式 $C = 3000 \\times \\log_2(1 + 1000) \\approx 3000 \\times 9.967 \\approx 29.9\\text{ kbps}$。可见受限于物理信噪比，传统拨号调制解调器无法突破约 $33.6\\text{ kbps}$ 极限。"}, {"oj": "教材精选题", "pid": "NET-2.2", "title": "奈奎斯特与香农联合约束求最大调制电平数", "diff": "中档", "hint": "破题思路：信道带宽 $B = 4\\text{ kHz}$，信噪比 $20\\text{ dB}$，若采用离散电平调制，最大有意义的电平数 $V$ 是多少？\n解答要点：$S/N = 10^{20/10} = 100$，香农极限 $C = 4000 \\log_2(101) \\approx 26.63\\text{ kbps}$。受奈奎斯特 $2B \\log_2 V \\le 26.63\\text{ kbps}$ 限制，得 $8000 \\log_2 V \\le 26630 \\implies \\log_2 V \\le 3.33$，故最多采用 $2^3 = 8$ 个有效电平（若用 $V=16$ 则超出香农极限导致误码激增）。"}, {"oj": "教材精选题", "pid": "NET-2.3", "title": "曼彻斯特编码 vs 差分曼彻斯特编码波形还原", "diff": "中档", "hint": "破题思路：给定比特流 `010011`，对比两种编码的跳变规律。\n解答要点：标准曼彻斯特（802.3 约定 0=高到低，1=低到高）在每个比特周期中点必跳变；差分曼彻斯特则是每比特中点恒跳变提供时钟，而比特边界是否跳变代表数据（边界有跳变为 0，无跳变为 1），具有极强的抗反相接线容错能力。"}, {"oj": "教材精选题", "pid": "NET-2.4", "title": "4B/5B 编码与百兆以太网实际物理链路波特率推导", "diff": "压轴", "hint": "破题思路：100BASE-TX 以太网有效数据速率为 $100\\text{ Mbps}$，采用 4B/5B 编码后再用 MLT-3（三电平）调制。\n解答要点：4B/5B 编码效率为 $80\\%$，故编码后比特率提升至 $100 / 0.8 = 125\\text{ Mbps}$。由于 MLT-3 每次仅在 `-1, 0, +1, 0` 间循环变化（最多每 4 个符号完成一个完整基频周期），其基频（奈奎斯特带宽）仅需 $125 / 4 = 31.25\\text{ MHz}$，从而能跑在低成本的超五类双绞线上。"}]}, {"cid": "net_ch3", "title": "第3章 应用层协议：HTTP 演进、DNS 解析链与 P2P 分发", "summary": "本章自顶向下剖析典型互联网应用层协议的交互范式。Web 传输经历了从 HTTP/1.0 短连接（每对象 1 次 TCP 握手）、HTTP/1.1 持久连接（仍受队头阻塞 HOL Blocking 困扰）到 HTTP/2 多路复用二进制帧与 HTTP/3（基于 QUIC/UDP 消除传输层队头阻塞）的演进。DNS 域名系统依托根、顶级域（TLD）与权威域名服务器构成的分布式层次数据库，结合本地 DNS 缓存，通过“客户端到本地域名服务器的递归查询”与“本地域名服务器向各级服务器的迭代查询”完成域名到 IP 的映射。此外，P2P 文件分发（如 BitTorrent）利用“一报还一报”（Tit-for-Tat）稀疏博弈机制激励节点互助上传，使总分发时间随节点数增长几乎保持常数级。", "template_cpp": "// HTTP/1.0 vs HTTP/1.1 持久连接页面加载 RTT 计算模型\ndouble http_load_time(int num_objs, double rtt, bool persistent, bool pipelining) {\n    if (!persistent) return (1 + num_objs) * 2.0 * rtt; // 每对象均需 TCP+HTTP = 2 RTT\n    if (!pipelining) return 2.0 * rtt + num_objs * rtt; // 1次握手 + 基页 + N次串行\n    return 3.0 * rtt; // 握手 + 基页 + 并行流水线\n}", "pitfalls": "1. 误以为 HTTP/1.1 流水线（Pipelining）彻底解决了队头阻塞，实际上服务器仍必须按请求顺序返回响应；2. 混淆 DNS 记录类型：`A`（主机名->IPv4）、`NS`（域->权威DNS名）、`CNAME`（别名->规范名）、`MX`（邮件域->邮件服务器名）；3. 计算 HTTP 加载时间时漏算基 HTML 文档本身的 1 个 RTT 或 TCP 三次握手（忽略传输时间时握手占 1 RTT）。", "workbench_tags": ["HTTP演进", "DNS递归与迭代", "P2P分发模型", "RTT延迟分析"], "problems": [{"oj": "教材精选题", "pid": "NET-3.1", "title": "含 8 个小对象的网页在 HTTP/1.0 与持久 HTTP/1.1 下的加载时间", "diff": "基础", "hint": "破题思路：假设 DNS 已缓存，客户端与服务器间 $RTT = 20\\text{ ms}$，小对象传输时间忽略不计。\n解答要点：非持久 HTTP/1.0（串行无并发）：基文档 2 RTT + 8 个对象各 2 RTT = $18\\text{ RTT} = 360\\text{ ms}$。持久非流水线 HTTP/1.1：1 RTT 握手 + 1 RTT 取基文档 + 8 RTT 串行取对象 = $10\\text{ RTT} = 200\\text{ ms}$。"}, {"oj": "教材精选题", "pid": "NET-3.2", "title": "DNS 混合递归-迭代解析的完整报文交互与 RTT 计数", "diff": "中档", "hint": "破题思路：客户端查询 `cs.example.edu`，本地 DNS 缓存为空，每次向外部 DNS 查询往返均为 $RTT_{dns}$。\n解答要点：1. 客户端 -> 本地 DNS（递归）；2. 本地 DNS -> 根服务器（返回 `.edu` TLD 地址）；3. 本地 DNS -> `.edu` TLD（返回 `example.edu` 权威服务器）；4. 本地 DNS -> 权威服务器（返回 `cs.example.edu` 的 A 记录）；5. 本地 DNS -> 客户端。共消耗 $1\\text{ (本地)} + 3\\text{ (外部)}$ 次 RTT。"}, {"oj": "教材精选题", "pid": "NET-3.3", "title": "C/S 架构与 P2P 架构文件分发最小时间对比", "diff": "中档", "hint": "破题思路：文件大小 $F = 15\\text{ Gbits}$，服务器上传 $u_s = 30\\text{ Mbps}$，共 $N = 100$ 个节点，每节点下载 $d_i = 2\\text{ Mbps}$、上传 $u_i = 0.3\\text{ Mbps}$。\n解答要点：C/S 最小时间 $D_{CS} = \\max(NF / u_s, F / d_{\\min}) = \\max(100\\times 15000 / 30, 15000 / 2) = 50000\\text{ s}$。P2P 最小时间 $D_{P2P} = \\max\\left(\\frac{F}{u_s}, \\frac{F}{d_{\\min}}, \\frac{NF}{u_s + \\sum u_i}\\right) = \\max(500, 7500, \\frac{1500000}{30 + 30}) = 25000\\text{ s}$。"}, {"oj": "教材精选题", "pid": "NET-3.4", "title": "HTTP/2 多路复用 vs HTTP/3 (QUIC) 在丢包场景下的队头阻塞差异", "diff": "压轴", "hint": "破题思路：同一网页包含 4 个并发资源流，假设底层网络发生 1 个数据包丢失，分析 HTTP/2 与 HTTP/3 的行为差异。\n解答要点：HTTP/2 将所有 4 个流复用在单条 TCP 连接上，TCP 要求字节流严格按序交付，因此 1 个包丢失会冻结全部 4 个流的交付（传输层队头阻塞）；HTTP/3 基于运行在 UDP 之上的 QUIC，每个流拥有独立编号与重传控制，单包丢失仅阻塞对应流，其余 3 个流可立即向上交付。"}]}, {"cid": "net_ch4", "title": "第4章 传输层基础：多路复用、UDP 校验和与可靠传输 RDT", "summary": "传输层在不可靠的 IP 网络之上提供进程到进程的逻辑通信。无连接的 UDP 通过目的端口号实现多路分解，仅附加极简的 8 字节首部与端到端校验和（反码求和）。为在可能丢包、比特翻转的信道上实现可靠数据传输（RDT），协议通过序列号、确认（ACK）、定时器与滑动窗口构建了三类经典模型：停等协议（Stop-and-Wait，信道利用率受限）；回退 N 步（GBN，接收方仅缓存按序分组，累积确认，单包丢失触发后续全部重传）；选择重传（SR，接收方缓存乱序分组并单独确认，仅重传超时分组）。为避免新旧序列号空间重叠导致的歧义，若序列号占 $k$ 比特，GBN 窗口上限为 $2^k - 1$，而 SR 收发窗口之和不能超过 $2^k$（等长时各自上限为 $2^{k-1}$）。", "template_cpp": "// 16-bit 互联网校验和 (UDP/TCP/IP 通用反码求和)\n#include <cstdint>\nuint16_t internet_checksum(const uint16_t* data, int len_bytes) {\n    uint32_t sum = 0;\n    while (len_bytes > 1) { sum += *data++; len_bytes -= 2; }\n    if (len_bytes == 1) sum += *(const uint8_t*)data;\n    while (sum >> 16) sum = (sum & 0xFFFF) + (sum >> 16);\n    return (uint16_t)(~sum);\n}", "pitfalls": "1. 计算 UDP 校验和时忘记包含 12 字节伪首部（源/目的 IP、协议号 17、UDP 长度）；2. 将 GBN 窗口大小上限（$2^k - 1$）与 SR 窗口大小上限（$2^{k-1}$）记混；3. 计算停等协议利用率时把分母写成 $L/R$ 而漏掉加上 $RTT$（$U = \\frac{L/R}{RTT + L/R}$）。", "workbench_tags": ["UDP校验和", "停等协议利用率", "GBN回退N步", "SR选择重传"], "problems": [{"oj": "教材精选题", "pid": "NET-4.1", "title": "16位反码求和（UDP 校验和）计算与单比特翻转漏检分析", "diff": "基础", "hint": "破题思路：求三个 16 位字 `0110011001100000`、`0101010101010101`、`1000111100001100` 的校验和。\n解答要点：前两数相加得 `1011101110110101`；再加第三数产生最高位进位 `1`：`1_0100101011000001`，回卷进位加 1 得 `0100101011000010`，逐位取反得校验和 `1011010100111101`。若其中两字同一比特位同时发生相反方向翻转（0变1与1变0），总和不变，校验和无法检出。"}, {"oj": "教材精选题", "pid": "NET-4.2", "title": "高时延带宽积链路下停等协议 vs 流水线窗口利用率", "diff": "中档", "hint": "破题思路：链路速率 $R = 1\\text{ Gbps}$，单向传播 $15\\text{ ms}$（$RTT = 30\\text{ ms}$），分组长 $L = 8000\\text{ bits}$。\n解答要点：单包发送耗时 $d_{trans} = 8000 / 10^9 = 8\\text{ }\\mu\\text{s} = 0.008\\text{ ms}$。停等利用率 $U = \\frac{0.008}{30 + 0.008} \\approx 0.027\\%$。欲使利用率达到 $90\\%$，需窗口大小 $N \\ge 0.9 \\times (30.008 / 0.008) \\approx 3376$ 个分组。"}, {"oj": "教材精选题", "pid": "NET-4.3", "title": "选择重传（SR）序列号歧义边界反例构造", "diff": "中档", "hint": "破题思路：序列号空间为 `0, 1, 2, 3`（$k=2$），若误将 SR 发送/接收窗口均设为 $W=3$（超出了 $2^{k-1}=2$），构造导致接收方把新包误判为旧包重传的序列。\n解答要点：发送方发 `0, 1, 2`，接收方全收到并推进窗口至 `[3, 0, 1]`，回送 `ACK 0, 1, 2`；若这 3 个 ACK 全部丢失，发送方超时重传 `0`，接收方此时窗口正包含 `0`，无法区分这是旧 `0` 还是新一轮的 `0`，导致数据错乱。"}, {"oj": "教材精选题", "pid": "NET-4.4", "title": "GBN 与 SR 在固定丢包率下的重传开销定量比较", "diff": "压轴", "hint": "破题思路：窗口大小 $W=10$，发送方连续发完 10 个分组时第 2 号分组丢失，其余 9 个均成功到达，比较 GBN 与 SR 的总发送次数。\n解答要点：GBN 中接收方丢弃第 $3\\sim 10$ 号乱序包并重复发送 `ACK 1`，发送方超时后必须重传第 $2\\sim 10$ 号共 9 个包，总发送 $10 + 9 = 19$ 次；SR 中接收方缓存 $3\\sim 10$ 号并返回各自 ACK，发送方仅重传第 2 号包，总发送 $10 + 1 = 11$ 次。"}]}, {"cid": "net_ch5", "title": "第5章 TCP 协议核心：连接状态机、流量控制与拥塞控制", "summary": "TCP 提供面向连接、全双工、可靠的字节流服务。三次握手（SYN -> SYN+ACK -> ACK）同步初始序列号 ISN 并防历史失效连接；四次挥手后主动关闭方进入 `TIME_WAIT` 等待 $2MSL$，确保被动方收到 ACK 且旧包在网络中消逝。接收方通过通告窗口 `rwnd` 实施端到端流量控制。拥塞控制动态维护 `cwnd`：慢启动每 RTT 指数翻倍直至阈值 `ssthresh`；拥塞避免转为线性增长（AIMD）；3 次冗余 ACK 触发快重传与快恢复（`ssthresh = cwnd/2, cwnd = ssthresh + 3`），而超时（Timeout）则退回 `cwnd = 1` 重新慢启动。", "template_cpp": "// TCP Reno 拥塞控制状态机核心转移伪代码\nif (event == NEW_ACK) {\n    if (cwnd < ssthresh) cwnd += 1;           // 慢启动 (指数增长)\n    else cwnd += 1.0 / cwnd;                  // 拥塞避免 (每RTT加1)\n} else if (event == TRIPLE_DUP_ACK) {\n    ssthresh = max(2, cwnd / 2);\n    cwnd = ssthresh + 3;                      // 快速恢复\n} else if (event == TIMEOUT) {\n    ssthresh = max(2, cwnd / 2);\n    cwnd = 1;                                 // 回退至慢启动\n}", "pitfalls": "1. 三次握手中的 `SYN` 和四次挥手里的 `FIN` 均消耗 1 个序列号（即使载荷为 0 字节），而纯 `ACK` 不消耗序列号；2. 混淆流量控制（保护接收方缓冲区不溢出，`rwnd`）与拥塞控制（保护中间网络路由器不拥塞，`cwnd`），实际发送窗口为 $\\min(cwnd, rwnd)$；3. 计算 RTT 估计值时漏掉偏差 `DevRTT` 对超时时间 $RTO = EstimatedRTT + 4 \\times DevRTT$ 的贡献。", "workbench_tags": ["TCP三次握手", "TIME_WAIT", "AIMD拥塞控制", "快重传快恢复"], "problems": [{"oj": "教材精选题", "pid": "NET-5.1", "title": "TCP 三次握手与数据传输序列号/确认号精确追踪", "diff": "基础", "hint": "破题思路：Client `ISN=100`，Server `ISN=300`，握手后 Client 发送 500 字节请求，Server 回复 1200 字节响应。\n解答要点：1. `SYN, seq=100`；2. `SYN+ACK, seq=300, ack=101`；3. `ACK, seq=101, ack=301`；4. Client 发数据：`seq=101, ack=301, len=500`；5. Server 回复：`seq=301, ack=601, len=1200`；6. Client 确认：`seq=601, ack=1501`。"}, {"oj": "教材精选题", "pid": "NET-5.2", "title": "TCP Reno 拥塞窗口演化曲线与各轮次数值追踪", "diff": "中档", "hint": "破题思路：初始 `cwnd=1 MSS, ssthresh=8 MSS`，第 4 轮触发 3 次冗余 ACK，第 7 轮发生 Timeout。\n解答要点：第 1~3 轮慢启动：`cwnd` 为 `1 -> 2 -> 4 -> 8`（达 `ssthresh`）；第 4 轮线性增至 `9` 时遇 3 个冗余 ACK，进入快恢复：`ssthresh = 9/2 = 4`（向下取整），`cwnd = 4 + 3 = 7`（或恢复后设为 4）；第 5~6 轮线性增至 `5 -> 6`；第 7 轮遇 Timeout，`ssthresh = 3, cwnd = 1`。"}, {"oj": "教材精选题", "pid": "NET-5.3", "title": "Jacobson/Karels TCP RTO 超时重传定时器更新", "diff": "中档", "hint": "破题思路：已知 $EstimatedRTT = 100\\text{ ms}, DevRTT = 5\\text{ ms}$，新测得 $SampleRTT = 140\\text{ ms}$，取 $\\alpha = 0.125, \\beta = 0.25$。\n解答要点：$EstimatedRTT' = 0.875\\times 100 + 0.125\\times 140 = 87.5 + 17.5 = 105\\text{ ms}$；$DevRTT' = 0.75\\times 5 + 0.25\\times |140 - 105| = 3.75 + 8.75 = 12.5\\text{ ms}$；新超时时间 $RTO = 105 + 4 \\times 12.5 = 155\\text{ ms}$。"}, {"oj": "教材精选题", "pid": "NET-5.4", "title": "长肥管道（LFN）下 TCP 稳态吞吐量公式与丢包率约束", "diff": "压轴", "hint": "破题思路：利用经典 Mathis 公式 $T \\approx \\frac{1.22 \\cdot MSS}{RTT \\sqrt{p}}$，欲在 $RTT = 100\\text{ ms}$、$MSS = 1460\\text{ B}$ 的跨洋链路上跑满 $10\\text{ Gbps}$，求允许的最大丢包率 $p$。\n解答要点：平均吞吐 $10^{10}\\text{ bps} = 1.25 \\times 10^9\\text{ B/s}$。代入得 $\\sqrt{p} \\approx \\frac{1.22 \\times 1460}{0.1 \\times 1.25 \\times 10^9} \\approx 1.425 \\times 10^{-5}$，平方得 $p \\approx 2 \\times 10^{-10}$，这解释了为什么高带宽长距离链路需要 TCP CUBIC 或 BBR 替代传统 Reno。"}]}, {"cid": "net_ch6", "title": "第6章 网络层（数据平面）：CIDR 子网划分、IP 分片与 NAT", "summary": "网络层数据平面负责将 IP 数据报从源主机逐跳转发至目的主机。无类别域间路由（CIDR）打破传统 A/B/C 类限制，用“网络前缀/掩码长度”表达地址块，路由器依据“最长前缀匹配”（Longest Prefix Matching）原则查询转发表。当数据报长度超过下一跳链路的 MTU（如以太网 1500B）时，路由器对其进行 IPv4 分片，各分片继承相同的 `ID`，并用 8 字节为单位的 `Offset` 与 `MF`（More Fragments）标志位供目的主机重组。针对 IPv4 地址枯竭，网络地址转换（NAT）在边缘路由器维护 `(内网IP:端口) <-> (公网IP:端口)` 映射表，使局域网内多台主机共享单一公网 IP 访问外部服务。", "template_cpp": "// IPv4 CIDR 最长前缀匹配与子网归属判定\n#include <cstdint>\nbool match_prefix(uint32_t ip, uint32_t net, int prefix_len) {\n    if (prefix_len == 0) return true;\n    uint32_t mask = 0xFFFFFFFFu << (32 - prefix_len);\n    return (ip & mask) == (net & mask);\n}", "pitfalls": "1. 计算 IPv4 分片载荷时忘记减去 20 字节 IP 首部，且每个非末分片的数据长度必须是 `8` 字节的整数倍（因为片偏移 `Offset` 以 8 字节为步长）；2. 子网划分时忘记扣除全 0 网络地址与全 1 广播地址，实际可用主机数为 $2^{32-n} - 2$；3. 路由聚合（超网）时把不同长度的前缀强行合并，导致把原本不属于该机构的 IP 段也错误包含进来。", "workbench_tags": ["CIDR最长前缀匹配", "VLSM子网划分", "IPv4分片重组", "NAT端口映射"], "problems": [{"oj": "教材精选题", "pid": "NET-6.1", "title": "VLSM 可变长子网掩码按需分配地址块", "diff": "基础", "hint": "破题思路：机构获得 `192.168.10.0/24`，需划分为 A（100 台主机）、B（50 台）、C（20 台）三个子网。\n解答要点：按需求从大到小分配：A 需至少 $100+2=102 \\le 2^7$，取 `/25`（`192.168.10.0/25`，可用 `.1~.126`）；B 需 $50+2=52 \\le 2^6$，取 `/26`（`192.168.10.128/26`，可用 `.129~.190`）；C 需 $20+2=22 \\le 2^5$，取 `/27`（`192.168.10.192/27`，可用 `.193~.222`）。"}, {"oj": "教材精选题", "pid": "NET-6.2", "title": "IPv4 大数据包跨小 MTU 链路的精确分片参数计算", "diff": "中档", "hint": "破题思路：总长 4000B 的 IPv4 数据报（首部 20B，载荷 3980B，ID=777）通过 MTU=1500B 的链路。\n解答要点：每片最大载荷 $1500 - 20 = 1480\\text{ B}$，恰好是 8 的倍数（$1480/8=185$）。分片 1：`总长=1500, MF=1, Offset=0`；分片 2：`总长=1500, MF=1, Offset=185`；剩余载荷 $3980 - 2960 = 1020\\text{ B}$，故分片 3：`总长=1040, MF=0, Offset=370`。"}, {"oj": "教材精选题", "pid": "NET-6.3", "title": "路由表聚合与最长前缀匹配转发决策", "diff": "中档", "hint": "破题思路：转发表有 `10.1.0.0/21 -> 接口0`、`10.1.4.0/22 -> 接口1`、`10.1.6.0/24 -> 接口2`、`0.0.0.0/0 -> 接口3`，判断目的 IP `10.1.6.55` 与 `10.1.5.10` 的下一跳。\n解答要点：`10.1.6.55` 同时匹配 `/21`、`/22`、`/24`，按最长前缀匹配走 `接口2`；`10.1.5.10` 不匹配 `/24`，匹配 `/21` 与 `/22`，取更长的 `/22` 走 `接口1`。"}, {"oj": "教材精选题", "pid": "NET-6.4", "title": "NAT 穿透困境与对称 NAT 下的 P2P 打洞失效分析", "diff": "压轴", "hint": "破题思路：主机 A（`10.0.0.1:5000`）处于对称 NAT 后，与公网服务器 S 通信后想与主机 B 直连，分析为何直连失败。\n解答要点：在全锥形 NAT 中，内网端口映射到固定公网端口；而在对称 NAT 中，每次访问不同的目的 IP/端口，路由器都会分配全新的外部端口号。因此 S 看到的 A 的公网端口对 B 无效，必须依赖中继服务器（TURN）转发流量。"}]}, {"cid": "net_ch7", "title": "第7章 网络层（控制平面）：OSPF 链路状态、RIP 距离向量与 BGP", "summary": "网络层控制平面负责全网路由计算与转发表生成。域内路由（AS 内部）分为两派：链路状态算法（如 OSPF）由各节点泛洪链路开销构建全局拓扑图，再独立运行 Dijkstra 算法求单源最短路径，收敛快且无环路，复杂度 $O(E \\log V)$；距离向量算法（如 RIP）基于分布式 Bellman-Ford 方程 $D_x(y) = \\min_v \\{c(x,v) + D_v(y)\\}$，节点仅与直连邻居交换距离表，在链路开销变大或断开时易触发“无穷计数”（Count-to-Infinity）慢收敛问题（可通过毒性逆转部分缓解）。域间路由（AS 之间）则采用路径向量协议 BGP，基于商业策略而非单纯最短跳数选择无环 AS-PATH，并常以“热土豆路由”原则尽早将跨网流量甩向最近出口。", "template_cpp": "// Bellman-Ford 距离向量单步松弛更新模板\nfor (int v : neighbors[u]) {\n    for (int dest = 0; dest < N; ++dest) {\n        if (cost[u][v] + D[v][dest] < D[u][dest]) {\n            D[u][dest] = cost[u][v] + D[v][dest];\n            next_hop[u][dest] = v;\n        }\n    }\n}", "pitfalls": "1. 误以为毒性逆转（Poisoned Reverse）能解决所有距离向量环路，实际上三节点及以上构成的拓扑环路仍会出现无穷计数；2. 混淆 OSPF（运行在 IP 之上，协议号 89）、RIP（运行在 UDP 520 端口）与 BGP（运行在 TCP 179 端口）的承载协议；3. 忽略 BGP 路由选择中的商业策略优先级（LocalPref > 最短 AS-PATH > MED > 热土豆 IGP 开销）。", "workbench_tags": ["Dijkstra链路状态", "Bellman-Ford距离向量", "无穷计数", "BGP域间策略"], "problems": [{"oj": "教材精选题", "pid": "NET-7.1", "title": "6 节点拓扑上的 Dijkstra 链路状态最短路径树迭代追踪", "diff": "基础", "hint": "破题思路：给定无向带权图，从源点 `u` 出发，逐轮将未确定集合中距离最小的节点加入已确定集合 $N'$ 并松弛其邻居。\n解答要点：每轮记录 `N'` 与各节点当前 `(D(v), p(v))`：初始 `N'={u}`，更新直连邻居；第 2 轮选出最小邻居加入并更新其邻接点；依此类推至全图覆盖，按前驱 `p(v)` 反向追踪即可生成到所有节点的转发下一跳表。"}, {"oj": "教材精选题", "pid": "NET-7.2", "title": "距离向量链路断开引发无穷计数的逐轮追踪", "diff": "中档", "hint": "破题思路：拓扑 `x - y - z` 成线，`c(x,y)=4, c(y,z)=1`（`x` 无直连 `z`），初始 $D_y(x)=4, D_z(x)=5$。突然 `c(x,y)` 暴增至 `60`。\n解答要点：断联瞬间 `y` 看到邻居 `z` 声称 `D_z(x)=5`，于是误以为可通过 `z` 绕道去 `x`，更新 `D_y(x) = 1 + 5 = 6`；下轮 `z` 收到后更新 `D_z(x) = 7`，如此乒乓递增至 `50+` 才发现 `60` 更小。采用毒性逆转（`z` 向 `y` 撒谎 `D_z(x)=∞`）可在此双节点场景立即截断环路。"}, {"oj": "教材精选题", "pid": "NET-7.3", "title": "BGP 无谷策略（Gao-Rexford）防非商业中转路由", "diff": "中档", "hint": "破题思路：ISP 网络中存在客户（Customer）、对等（Peer）与提供商（Provider）三种商业关系，分析为何 AS B 不向两个 Provider（A 和 C）互相通告路由。\n解答要点：若 B 将从 Provider A 学来的路由通告给 Provider C，等于 B 免费帮 A 和 C 互相中转流量而自身还要付双份带宽费。因此 BGP 出口策略规定：从 Provider 或 Peer 学来的路由只能通告给自己的 Customer，绝不通告给其他 Provider 或 Peer。"}, {"oj": "教材精选题", "pid": "NET-7.4", "title": "BGP 选路优先级与热土豆（Hot-Potato）路由决策", "diff": "压轴", "hint": "破题思路：AS 1 内路由器 R1 收到前往某前缀的两条 BGP 路由：经出口 R2（IGP 开销 10，AS-PATH 长 3）与经出口 R3（IGP 开销 25，AS-PATH 长 2），假定两条路由 `LocalPref` 相同。\n解答要点：根据 BGP 决策顺序，先比较 `LocalPref`（相等），再比较 `AS-PATH` 长度（2 < 3），故选择 R3 而非 IGP 开销更小的 R2；唯有当两条路由的 `LocalPref`、`AS-PATH` 长度、`Origin` 与 `MED` 全部打平时，才触发热土豆规则选择内部 IGP 代价最小的出口 R2。"}]}, {"cid": "net_ch8", "title": "第8章 链路层与局域网：CRC 校验、CSMA/CD 与交换机自学习", "summary": "数据链路层负责相邻节点间的成帧、差错检测与多路访问控制。循环冗余校验（CRC）将比特流视为 $\\text{GF}(2)$ 多项式，除以 $r+1$ 位生成多项式 $G$ 得到 $r$ 位余数作为校验码，检错能力远超奇偶校验。在共享广播信道中，随机访问协议从纯 ALOHA（最大吞吐 $1/(2e) \\approx 18.4\\%$）、时隙 ALOHA（$1/e \\approx 36.8\\%$）演进到载波侦听多路访问/碰撞检测（CSMA/CD）：为保证发送方在发完帧前能检测到最远端的碰撞，最小帧长必须满足 $L_{min} \\ge 2 \\cdot \\frac{d}{v} \\cdot R$。现代交换式以太网通过交换机自学习（维护 `MAC -> 端口` 转发表）隔离碰撞域，并借助生成树协议（STP）消除二层广播风暴环路，同时由 ARP 协议完成同子网 IP 到 MAC 地址的动态解析。", "template_cpp": "// CRC-CCITT/通用多项式模 2 除法余数计算\n#include <cstdint>\nuint32_t crc_remainder(uint32_t data_shifted, uint32_t gen_poly, int data_bits, int r) {\n    for (int i = data_bits + r - 1; i >= r; --i) {\n        if ((data_shifted >> i) & 1)\n            data_shifted ^= (gen_poly << (i - r));\n    }\n    return data_shifted & ((1u << r) - 1);\n}", "pitfalls": "1. 计算 CRC 时忘记先在原始数据末尾补 $r$ 个 `0`（其中 $r$ 为生成多项式最高次幂）；2. 忘记跨路由器转发时帧的“源/目的 MAC 地址”每一跳都会改写，而“源/目的 IP 地址”（无 NAT 时）保持不变；3. 计算 CSMA/CD 最小帧长时漏乘往返系数 `2`（最坏情况信号从 A 到 B 再碰撞返回 A 需 $2 d_{prop}$）。", "workbench_tags": ["CRC循环冗余校验", "CSMA/CD最小帧长", "交换机自学习", "ARP地址解析"], "problems": [{"oj": "教材精选题", "pid": "NET-8.1", "title": "CRC 多项式模 2 除法编码与接收端检错验证", "diff": "基础", "hint": "破题思路：数据比特 `D = 101110`，生成多项式 $G = x^3 + 1$（即 `1001`，阶数 $r = 3$）。\n解答要点：先将 `D` 左移 3 位补零得 `101110000`，用 `1001` 进行模 2 异或除法：逐位对齐消去最高位 `1`，最终余数 $R = 011$。实际发送帧为 `101110011`。接收端用 `1001` 除 `101110011`，若余数为 `000` 则判定无差错。"}, {"oj": "教材精选题", "pid": "NET-8.2", "title": "千兆以太网 CSMA/CD 最小帧长与最大线缆长度推导", "diff": "中档", "hint": "破题思路：链路速率 $R = 100\\text{ Mbps}$，信号传播速度 $v = 2 \\times 10^8\\text{ m/s}$，以太网最小帧长 $64\\text{ B} = 512\\text{ bits}$，求最大无中继总线距离 $d_{max}$。\n解答要点：由 $L_{min} / R \\ge 2 d_{max} / v$，代入得 $512 / 10^8 \\ge 2 d_{max} / (2 \\times 10^8) \\implies d_{max} \\le 512\\text{ m}$（实际标准扣留物理层中继开销定为 $200\\sim 250\\text{ m}$）。可见速率升至 $10\\text{ Gbps}$ 时若保留碰撞检测，线长将缩水百倍，故万兆网已全面弃用半双工 CSMA/CD。"}, {"oj": "教材精选题", "pid": "NET-8.3", "title": "跨网段通信中 ARP 广播域边界与 MAC/IP 逐跳改写", "diff": "中档", "hint": "破题思路：主机 A（IP1/MAC1）通过路由器 R（左口 MAC_R1，右口 MAC_R2）向另一子网主机 B（IP2/MAC2）发包。\n解答要点：A 发现 IP2 不在本子网，于是发送目的 IP 为 IP2、目的 MAC 为默认网关 `MAC_R1` 的帧（ARP 仅解析同网段下一跳 MAC，绝不跨路由器）；R 收到后剥离旧帧头，查路由表并封装新帧头（源 `MAC_R2`，目的 `MAC2`），而内层 IP1 与 IP2 全程不变。"}, {"oj": "教材精选题", "pid": "NET-8.4", "title": "二进制指数退避算法（BEB）与吞吐量极限分析", "diff": "压轴", "hint": "破题思路：A、B 两站同时首次碰撞（$k=1$），从 $\\{0, 1\\}$ 选退避槽位；若再碰撞（$k=2$）从 $\\{0,1,2,3\\}$ 选，计算二次仍碰撞的概率及平均等待时隙。\n解答要点：$k=1$ 时再次碰撞概率为 $2 / 4 = 0.5$；若进入 $k=2$，两人均选相同槽位的概率为 $4 / 16 = 0.25$。一般地，第 $k$ 次碰撞后单次冲突概率降至 $2^{-\\min(k, 10)}$，在极端高负载下通过动态拉长退避窗口避免信道彻底崩溃。"}]}, {"cid": "net_ch9", "title": "第9章 无线网络与网络安全：CSMA/CA、公钥密码与 TLS 握手", "summary": "本章涵盖无线局域网 MAC 机制与端到端网络加密传输。IEEE 802.11 无线网络因信号衰减与无法边发边听，易发生“隐藏终端问题”，故弃用碰撞检测而采用带确认的碰撞避免协议 CSMA/CA：发送前侦听信道空闲满 DIFS 后随机退避，必要时先交换 RTS/CTS 预约信道并设置网络分配矢量 NAV 静默周围节点，接收方在 SIFS 后回传 ACK。网络安全体系结合了对称加密（AES，高速加解密）、非对称加密（RSA 与 Diffie-Hellman 密钥交换，解决分发难题）、密码散列（SHA-256）与数字签名（CA 证书防中间人攻击）。现代 HTTPS 依托 TLS 1.3 将握手压缩至 1-RTT：在 ClientHello 中直接携带 ECDHE 公钥分片，服务端回传公钥分片与 CA 证书签名即完成前向安全会话密钥协商。", "template_cpp": "// 教材经典 RSA 加解密与快速幂模运算模板\nlong long mod_pow(long long base, long long exp, long long mod) {\n    long long res = 1;\n    base %= mod;\n    while (exp > 0) {\n        if (exp & 1) res = (res * base) % mod;\n        base = (base * base) % mod;\n        exp >>= 1;\n    }\n    return res;\n}", "pitfalls": "1. 误以为数字签名是用“公钥加密”，实际上发送方用自己的“私钥”对报文摘要加密生成签名，接收方用发送方“公钥”解密验证；2. 混淆 SIFS（短帧间间隔，用于 ACK/CTS 等高优先级控制帧）与 DIFS（分布式帧间间隔，用于普通数据帧竞争）；3. 误以为 RSA 密钥交换具有前向安全性（Forward Secrecy），一旦服务器长期私钥泄露，历史截获的密文可被全部解密，因此 TLS 1.3 强制使用临时 ECDHE。", "workbench_tags": ["802.11 CSMA/CA", "隐藏终端RTS/CTS", "RSA与DH密钥交换", "TLS1.3握手"], "problems": [{"oj": "教材精选题", "pid": "NET-9.1", "title": "RSA 密钥生成、加密与私钥解密完整手算验证", "diff": "基础", "hint": "破题思路：选取素数 $p = 5, q = 11$，公钥指数 $e = 3$，明文 $m = 9$。\n解答要点：$n = p \\times q = 55$，欧拉函数 $\\phi(n) = (5-1)(11-1) = 40$。求 $d$ 满足 $3d \\equiv 1 \\pmod{40}$，解得 $d = 27$（因 $3 \\times 27 = 81 \\equiv 1$）。加密：$c = 9^3 \\bmod 55 = 729 \\bmod 55 = 14$。解密：$m = 14^{27} \\bmod 55$，利用快速幂 $14^2 \\equiv 31, 14^4 \\equiv 26, \\dots$ 还原得 $9$。"}, {"oj": "教材精选题", "pid": "NET-9.2", "title": "Diffie-Hellman 密钥协商与中间人攻击脆弱性", "diff": "中档", "hint": "破题思路：公开素数 $p = 23$，原根 $g = 5$，Alice 选私钥 $a = 6$，Bob 选私钥 $b = 15$。\n解答要点：Alice 发送 $A = 5^6 \\bmod 23 = 8$；Bob 发送 $B = 5^{15} \\bmod 23 = 19$。双方独立计算共享密钥：$K_A = 19^6 \\bmod 23 = 2$，$K_B = 8^{15} \\bmod 23 = 2$。但因 DH 本身不认证通信方身份，若中间人 Mallory 截获并分别与双方协商，可轻易实施中间人攻击，故必须结合 CA 数字证书签名。"}, {"oj": "教材精选题", "pid": "NET-9.3", "title": "802.11 RTS/CTS 预约机制解决隐藏终端干扰", "diff": "中档", "hint": "破题思路：A 与 C 均在 AP 覆盖范围内，但 A、C 互不可见（隐藏终端）。\n解答要点：A 发送短帧 RTS 给 AP，其中包含本次数据+ACK 所需总时长；AP 广播回复 CTS，C 虽听不到 A 的 RTS，但能听到 AP 的 CTS，于是读取其中的 Duration 字段并更新本地 NAV 计时器，在预约期间主动静默退避，从而保护 A 的长数据帧免遭碰撞。"}, {"oj": "教材精选题", "pid": "NET-9.4", "title": "TLS 1.2 (2-RTT) 与 TLS 1.3 (1-RTT) 握手延迟及安全机制对比", "diff": "压轴", "hint": "破题思路：对比两种版本从 TCP 建立后到发送首个加密 HTTP 请求的 RTT 消耗与密钥协商方式。\n解答要点：TLS 1.2 需先由 ClientHello/ServerHello 协商密码套件并传证书（1 RTT），再交换密钥参数并验证 Finished（第 2 RTT）才开始发应用数据；TLS 1.3 砍掉静态 RSA 等不安全套件，ClientHello 直接附带多个常见曲线的 `key_share` 猜测，ServerHello 同步回传 `key_share`、证书签名及 Finished，客户端收到后即可立即附带加密 HTTP 请求（1-RTT，支持会话票据时甚至 0-RTT）。"}]}]}, {"id": "gh_bupt_net", "name": "🎓 北邮 CS 学长攻略（计网 / 现代交换原理）", "author": "faranten/bupt-cs-gallery & Yokumii · GitHub", "level": "英文考试 + 跨章横向串联", "repo_url": "https://github.com/faranten/bupt-cs-gallery", "chapters": [{"cid": "BUPT-NET-01", "title": "北邮计算机网络（英文考试）与现代交换原理攻略", "summary": "北邮《计算机网络》采用 Tanenbaum《Computer Networks》体系且为【英文考试】（初学者也可辅以《Data Communications and Networking》理解，再回到工作台自顶向下串接）。拿高分的关键是【横向掌握】：把物理层编码、链路层 CSMA/CD 与滑动窗口、网络层 IP 分片/CIDR/OSPF/BGP、传输层 TCP 拥塞控制与应用层 DNS/HTTP 串联成完整一次网页访问链路。选修《现代交换原理》后半学期教材着墨少，务必紧盯老师 PPT 与课上研讨。", "template_cpp": "横向串联主线：输入 URL → DNS(UDP 53) → ARP 解析网关 MAC → TCP 三次握手 → TLS 握手 → HTTP 请求 → 路由器最长前缀匹配转发 → TCP 慢启动/拥塞避免。", "pitfalls": "只背单章孤立知识点，遇到跨层综合分析题（如 MTU 分片 + TCP MSS + 以太网最小帧长）直接卡壳。", "workbench_tags": ["北邮考情", "英文考试", "计网"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "计算机网络与通信 · 考前1页纸速查卡", "sections": [{"heading": "一、物理层、信息论与调制编码", "items": [{"name": "奈奎斯特准则 vs 香农信道容量", "formula": "$C_{\\text{Nyquist}} = 2B \\log_2 V,\\quad C_{\\text{Shannon}} = B \\log_2(1 + \\text{SNR}),\\quad \\text{SNR}_{\\text{dB}} = 10\\log_{10}\\text{SNR}$", "note": "考试常联合两式：先用香农算出最高容量 $C$，再反推允许的最大电平数 $V$；注意 dB 需先转线性比！"}, {"name": "香农极限与滚降升余弦波特率", "formula": "$\\lim_{B\\to\\infty} C \\implies \\left(\\frac{E_b}{N_0}\\right)_{\\min} = \\ln 2 \\approx -1.59\\text{ dB},\\quad R_s = \\frac{B}{1 + \\alpha}$", "note": "滚降系数 $\\alpha \\in [0,1]$：$\\alpha=0$ 时带宽利用率最高但对定时抖动极敏感。"}, {"name": "线路编码与直流分量/时钟同步", "formula": "$\\text{曼彻斯特效率 } 50\\%,\\quad \\text{4B/5B: } 80\\%,\\quad \\text{8B/10B: } 80\\%,\\quad \\text{64B/66B: } 96.97\\%$", "note": "100Mbps 以太网用 4B/5B + MLT-3（线路波特率 125MBd）；10GbE 用 64B/66B（线路速率 10.3125Gbps）。"}, {"name": "QAM 调制与格雷码映射", "formula": "$M\\text{-QAM 每符号比特 } k = \\log_2 M,\\quad R_b = R_s \\log_2 M$", "note": "星座图相邻点必须采用格雷码，确保噪声导致误判到相邻点时仅错 1 个比特。"}, {"name": "PCM 采样与 OFDM 正交子载波", "formula": "$f_s \\ge 2f_{\\max},\\ \\text{语音 } 8\\text{kHz}\\times 8\\text{bit}=64\\text{kbps};\\quad \\Delta f = \\frac{1}{T_u}$", "note": "OFDM 循环前缀 (CP) 将信道线性卷积转为圆周卷积消除 ISI；高速移动场景需加宽 $\\Delta f$ 抗多普勒频偏。"}]}, {"heading": "二、数据链路层、MAC 与以太网交换", "items": [{"name": "CRC 循环冗余校验与差错检测", "formula": "$\\text{发送帧} = M(x)\\cdot x^r \\oplus R(x),\\quad R(x) = [M(x)\\cdot x^r] \\bmod G(x)$", "note": "模 2 除法无借位（即异或）；生成多项式 $G(x)$ 含 $(x+1)$ 因式可检出所有奇数个比特错。"}, {"name": "CSMA/CD 最短帧长与效率", "formula": "$L_{\\min} = 2\\tau \\cdot R = 512\\text{ bit} = 64\\text{B}\\ (\\text{10M/100M}),\\quad \\eta = \\frac{1}{1 + 5a}\\ (a=\\frac{\\tau}{T_f})$", "note": "千兆以太网通过载波延伸将冲突槽扩至 512B；全双工交换以太网无冲突，不再使用 CSMA/CD。"}, {"name": "IEEE 802.3 以太网帧头与 Wireshark 60B/64B", "formula": "$\\text{8B 前导} + [\\text{6B DstMAC} + \\text{6B SrcMAC} + \\text{2B Type}] + \\text{46..1500B Data} + \\text{4B FCS}$", "note": "物理帧最小 64B（含 4B FCS），Wireshark 抓包通常由网卡剥离 FCS 故显示最短 60B。"}, {"name": "CSMA/CA 退避、NAV 与隐蔽站", "formula": "$\\text{DIFS} > \\text{PIFS} > \\text{SIFS},\\quad \\text{RTS/CTS 设 NAV 解决隐蔽终端问题}$", "note": "ACK 仅等 SIFS（最短帧间间隔）优先发出；数据帧需等 DIFS + 随机二进制指数退避。"}, {"name": "交换机自学习、VLAN 与 STP", "formula": "$\\text{学习源 MAC} \\to \\text{泛洪未知单播/广播},\\quad \\text{802.1Q 插入 4B Tag (TPID=0x8100 + 12b VID)}$", "note": "生成树协议 (STP/RSTP) 通过选举 Root Bridge 并阻塞冗余端口消除二层广播风暴环路。"}]}, {"heading": "三、网络层、IPv4/IPv6 与路由协议", "items": [{"name": "IPv4 首部 (20B) 关键字段与分片计算", "formula": "$\\text{Ver/IHL(1B) | TOS | Len(2B) | ID(2B) | Flags(3b)+Offset(13b) | TTL | Proto | Csum | Src/Dst(8B)}$", "note": "片偏移单位为 **8 字节**！除最后一片外，每片数据载荷长度必须是 8B 的整数倍。"}, {"name": "CIDR 子网划分与最长前缀匹配 (LPM)", "formula": "$\\text{可用主机数} = 2^{32 - /p} - 2,\\quad \\text{路由表按掩码长度 } /p \\text{ 降序匹配}$", "note": "子网聚合 (Route Aggregation) 要求连续地址块且前缀共同部分对齐，可减小骨干网路由表规模。"}, {"name": "RIP (DV) vs OSPF (LS) vs BGP", "formula": "$\\text{RIP: Bellman-Ford (UDP 520, 跳数}\\le 15),\\quad \\text{OSPF: Dijkstra (IP 89)},\\quad \\text{BGP: 路径矢量 (TCP 179)}$", "note": "RIP 存在慢收敛/计数到无穷，用水平分割+毒性逆转缓解；BGP 跨 AS 依据策略（LocalPref > AS-PATH > MED）。"}, {"name": "IPv6 固定首部 (40B) 与跨层地址规律", "formula": "$\\text{IPv6 取消首部校验和与中间路由器分片},\\quad \\text{跨路由器: IP 不变，MAC 逐跳变}$", "note": "IPv6 使用扩展首部链表与 Path MTU Discovery (ICMPv6 Packet Too Big) 替代中间节点分片。"}, {"name": "ARP、DHCP 与 NAT 穿透", "formula": "$\\text{ARP: 广播请求/单播响应 (IP}\\to\\text{MAC)},\\quad \\text{DHCP DORA: Discover-Offer-Request-Ack}$", "note": "NAPT (端口复用 NAT) 改写内网 IP 与源端口；同一子网直接 ARP 目标主机，跨子网 ARP 默认网关。"}]}, {"heading": "四、传输层、TCP 首部与拥塞控制", "items": [{"name": "TCP 首部 (20B) vs UDP 首部 (8B)", "formula": "$\\text{TCP: Src/Dst(4B) + Seq(4B) + Ack(4B) + Off/Flags(2B) + Win(2B) + Csum(2B) + Urg(2B)}$", "note": "UDP 仅 8B（源/目的端口、长度、校验和）；TCP/UDP 校验和均需拼接 12B 伪首部（含源/目的 IP）。"}, {"name": "三次握手与四次挥手关键机制", "formula": "$\\text{SYN/FIN 各消耗 1 个序号},\\quad \\text{RTT 估计: } \\text{SRTT} = (1-\\alpha)\\text{SRTT} + \\alpha R$", "note": "三次握手防止历史失效 SYN 报文建立重复连接；主动关闭方 TIME_WAIT 等待 2MSL。"}, {"name": "流量控制 (GBN/SR) 与停止等待效率", "formula": "$\\text{GBN: } W_S \\le 2^n - 1,\\quad \\text{SR: } W_S = W_R \\le 2^{n-1},\\quad U = \\frac{W \\cdot T_f}{T_f + \\text{RTT} + T_{\\text{ack}}}$", "note": "序号位数为 $n$ 时，选择重传 (SR) 发送与接收窗口均不可超序号空间一半，否则新旧帧混淆。"}, {"name": "TCP Reno vs CUBIC 拥塞控制", "formula": "$\\text{慢启动: } cwnd\\text{ 每 RTT 翻倍},\\quad \\text{3-Dup-ACK: } ssthresh=\\frac{cwnd}{2},\\ cwnd=ssthresh+3\\text{MSS}$", "note": "超时 (RTO) 触发 $ssthresh=cwnd/2$ 且 $cwnd=1\\text{MSS}$；3 次冗余 ACK 触发快重传与快恢复。"}, {"name": "QUIC 协议核心改进", "formula": "$\\text{基于 UDP} + \\text{0-RTT/1-RTT 建连} + \\text{流级多路复用 (消除队头阻塞)} + \\text{Connection ID 迁移}$", "note": "TCP 单连接丢一个包会阻塞所有 HTTP/2 流，QUIC 各 Stream 独立重传，且加密传输层首部防中间盒僵化。"}]}, {"heading": "五、现代交换、MPLS 与 SDN", "items": [{"name": "MPLS 标签结构 (4B) 与转发", "formula": "$\\text{Label(20b) | TC/EXP(3b) | S(1b 栈底) | TTL(8b)},\\quad \\text{Push / Swap / Pop}$", "note": "2.5 层转发位于链路头与 IP 头之间；倒数第二跳弹出 (PHP) 减少出口 LER 两次查表开销。"}, {"name": "SDN 控制面/数据面分离与 OpenFlow", "formula": "$\\text{Match (流表字段) + Priority + Action (Forward/Drop/Modify/Controller)}$", "note": "控制器通过南向接口（如 OpenFlow/P4Runtime）下发流表，实现全局视图下的流量工程与集中路由。"}, {"name": "交换矩阵：Crossbar 与 HOL 阻塞", "formula": "$\\text{单输入队列 (FIFO) 队头阻塞吞吐上限} = 2 - \\sqrt{2} \\approx 58.6\\%$", "note": "采用虚拟输出队列 (VOQ) 为每个输出端口维护独立队列，配合 iSLIP 调度可消除 HOL 阻塞。"}, {"name": "数据中心 Clos 拓扑与 ECMP", "formula": "$\\text{Spine-Leaf 全二分互联},\\quad \\text{Hash(5-Tuple)} \\bmod N \\text{ 等价多路径负载均衡}$", "note": "ECMP 对同一流哈希到固定路径保证不乱序，但大象流碰撞时需依赖流切片或包喷洒改进。"}, {"name": "RDMA over Converged Ethernet (RoCEv2)", "formula": "$\\text{PFC (基于优先级流控)} + \\text{ECN/DCQCN (端到端拥塞通知)} \\implies \\text{无损以太网}$", "note": "绕过 OS 内核协议栈实现网卡直接读写远端内存，支撑 AI 集群超低延迟 AllReduce 通信。"}]}, {"heading": "六、应用层、TLS 安全与 epoll 实战", "items": [{"name": "HTTP/1.1 vs HTTP/2 vs HTTP/3", "formula": "$\\text{1.1: 持久连接/管线队头阻塞} \\to \\text{2: 二进制帧+HPACK+多路复用} \\to \\text{3: QUIC/UDP}$", "note": "HTTP/2 虽在应用层多路复用，但在丢包高的无线环境下仍受制于底层 TCP 队头阻塞。"}, {"name": "DNS 解析流程与记录类型", "formula": "$\\text{本地缓存} \\to \\text{递归解析器 (UDP 53)} \\to \\text{根} \\to \\text{TLD} \\to \\text{权威 (迭代)}$", "note": "A/AAAA 映射 IPv4/IPv6，CNAME 为别名，MX 为邮件服务器；响应超 512B（无 EDNS0）或区域传送切 TCP 53。"}, {"name": "TLS 1.3 握手与前向安全 (PFS)", "formula": "$\\text{1-RTT (ECDHE 密钥协商 + 证书 + Finished)},\\quad \\text{0-RTT PSK (防重放限制)}$", "note": "TLS 1.3 废除静态 RSA 密钥交换与不安全加密套件，强制使用临时 ECDHE 保证前向安全性。"}, {"name": "非对称加密、数字签名与数字证书", "formula": "$\\text{加密: 用对方公钥},\\quad \\text{签名: 用自己私钥签 } H(m),\\quad \\text{CA 证书链验证公钥归属}$", "note": "实际传输用非对称密钥协商出对称会话密钥（如 AES-GCM），再由对称加密承载高速数据。"}, {"name": "Socket 高并发 Reactor 模型", "formula": "$\\text{listen(fd, backlog)} \\to \\text{epoll\\_wait} \\to \\text{非阻塞 read/write + 粘包长度头帧定界}$", "note": "TCP 是字节流无消息边界，应用层必须用定长、分隔符或 Length-Prefix 协议解决粘包/半包。"}]}, {"heading": "七、高频易错点与考场避坑清单", "items": [{"name": "比特 (b) vs 字节 (B) 与 1000 vs 1024", "formula": "$1\\text{ Gbps} = 10^9\\text{ bps},\\quad 1\\text{ KB} = 2^{10}\\text{ B} = 1024\\text{ B}$", "note": "通信速率（bps/Hz）一律按 $10^3$ 进制，存储/报文长度（B/KB）按 $2^{10}$ 进制，混用必算错！"}, {"name": "传播时延 vs 发送 (传输) 时延", "formula": "$d_{\\text{prop}} = \\frac{\\text{距离}}{v\\ (2\\times 10^8\\text{ m/s})},\\quad d_{\\text{trans}} = \\frac{\\text{帧长 } L}{\\text{带宽 } R}$", "note": "光纤中电磁波速度约 $2\\times 10^8\\text{ m/s}$（铜线约 $2\\sim 2.3\\times 10^8$），不是真空光速 $3\\times 10^8$。"}, {"name": "IPv4 分片偏移必须乘/除 8", "formula": "$\\text{MF}=1 \\implies \\text{载荷字节数必为 } 8 \\text{ 的倍数},\\quad \\text{Offset} = \\frac{\\text{字节起始位置}}{8}$", "note": "注意载荷长度不含 20B IP 首部！若 MTU=1500B，单片最大载荷为 $\\lfloor 1480/8\\rfloor\\times 8 = 1480\\text{B}$。"}, {"name": "子网网络地址与广播地址不可分配", "formula": "$\\text{主机位全 } 0 = \\text{网络号},\\quad \\text{主机位全 } 1 = \\text{广播地址}$", "note": "例外：点对点链路 /31 (RFC 3021) 可用 2 个地址；/32 表示单台主机路由。"}, {"name": "TCP 拥塞窗口单位：字节 vs MSS", "formula": "$\\text{收到 1 个有效 ACK} \\implies \\text{慢启动 } cwnd \\mathrel{+}= \\text{MSS},\\quad \\text{拥塞避免 } cwnd \\mathrel{+}= \\frac{\\text{MSS}^2}{cwnd}$", "note": "慢启动阶段每个新 ACK 加 1 MSS，故 1 个 RTT 后翻倍；拥塞避免每收到一整窗 ACK 才加 1 MSS。"}]}]};
